/** Isolated UI-test records generated by the real engine; never reads user storage. */
import { writeFileSync } from "node:fs";
import {
  createSession,
  answerQuestion,
  advanceQuestion,
  finishSession,
  type Session,
} from "../src/domain/game/engine";
import { gameQuestion } from "../src/content/questions/registry";
import { emptyData, parseData, STORAGE_KEY } from "../src/storage/schema";
const data = emptyData();
function complete(initial: Session, correct: number) {
  let session = initial;
  for (let i = 0; i < 10; i++) {
    const q = gameQuestion(session, session.questionIds[i]!)!;
    session = answerQuestion(
      session,
      i < correct ? q.correct : (q.correct + 1) % 4,
      session.startedAt + 1000 + i * 2000,
    );
    if (i < 9) session = advanceQuestion(session);
  }
  return finishSession(session);
}
const now = Date.now();
data.games = [
  complete(
    createSession("mixed", undefined, now - 180_000, { random: () => 0.41 }),
    7,
  ),
  complete(
    createSession("focus", "general", now - 120_000, { random: () => 0.21 }),
    6,
  ),
  complete(
    createSession("focus", "quran", now - 60_000, { random: () => 0.61 }),
    1,
  ),
];
data.profile.name = "Deneme Oyuncusu";
writeFileSync(
  process.env.UI_FIXTURE_PATH ?? "/tmp/premium-ui-fixture.json",
  JSON.stringify({
    storageKey: STORAGE_KEY,
    data: parseData(JSON.stringify(data)),
  }),
);
